 async function takePhoto(){photo=true;document.body.classList.add('life-photo-mode');api.close();api.notify('PHOTO MODE · Click the camera to save. Esc exits.');const bar=document.createElement('div');bar.id='lifePhotoBar';bar.innerHTML='<button id="lifeCapture">SAVE PHOTO</button><button id="lifeEndPhoto">BACK TO CITY</button>';document.body.append(bar);$('lifeEndPhoto').onclick=endPhoto;$('lifeCapture').onclick=()=>api.photo();}
